/**
 * Shared contract for the Trello-style board. Plain data only.
 *
 * @typedef {Object} Card
 * @property {number} id        unique across the board
 * @property {string} title
 * @property {string[]} labels  free-form tags, e.g. ['bug']
 * @property {string} listId    id of the list currently holding the card
 *
 * @typedef {Object} List
 * @property {string} id        kebab-case slug of the title, e.g. 'in-progress'
 * @property {string} title
 * @property {Card[]} cards     in display order, top to bottom
 *
 * @typedef {Object} BoardSnapshot
 * @property {List[]} lists     in display order, left to right
 */

/** Lists a new board starts with when none are given. */
const DEFAULT_LISTS = Object.freeze(['To Do', 'In Progress', 'Done'])

/** Turns a list title into its id: lowercase, non-alphanumerics collapsed to '-'. */
function slugify(title) {
  return String(title).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
}

module.exports = { DEFAULT_LISTS, slugify }

/** The board store: ordered lists of ordered cards. */

/**
 * @param {{ lists?: string[] }} [options] list titles; defaults to DEFAULT_LISTS
 * @returns {{
 *   snapshot(): import('../board/contract.js').BoardSnapshot,
 *   addList(title: string): import('../board/contract.js').List,
 *   addCard(listId: string, title: string, options?: { labels?: string[] }): import('../board/contract.js').Card | null,
 *   moveCard(cardId: number, toListId: string, toIndex?: number): import('../board/contract.js').Card | null,
 *   removeCard(cardId: number): boolean,
 * }}
 * snapshot() returns deep copies. addCard/moveCard return null for an unknown list or card.
 * moveCard appends when toIndex is omitted and clamps it into range otherwise.
 */
function createBoard(options = {}) {
  throw new Error('createBoard: not implemented')
}

module.exports = { createBoard }

/**
 * Renders a BoardSnapshot as side-by-side text columns, one per list.
 * Each column header shows the list title and card count, e.g. 'To Do (2)'.
 * Each card shows '#<id> <title>' and its labels as '[label]'. An empty list shows '(empty)'.
 * Titles longer than columnWidth are truncated with '...'.
 *
 * @param {import('../../board/contract.js').BoardSnapshot} board
 * @param {{ columnWidth?: number }} [options] default 24
 * @returns {string}
 */
function renderBoard(board, options = {}) {
  throw new Error('renderBoard: not implemented')
}

module.exports = { renderBoard }
